.leader-card .lc-awake { position: absolute; z-index: 4; top: 3px; left: 3px; padding: 2px 4px; border-radius: 2px; background: linear-gradient(90deg, #ffe58a, #ff9f1c); color: #321100; font-size: 5.5px; letter-spacing: .7px; font-weight: 900; }
.leader-card.can-attack { animation: attackReady 2.6s ease-in-out infinite; border-color: #ffe58a; box-shadow: 0 0 0 1px rgba(255, 207, 92, .6), 0 0 22px rgba(255, 207, 92, .28); }
.leader-card.selected-attacker { transform: translateY(-8px) scale(1.04); box-shadow: 0 0 0 2px rgba(255, 207, 92, .55), 0 0 30px rgba(255, 138, 30, .45); }
.leader-card.targetable { border-color: #ff4767; box-shadow: 0 0 0 2px rgba(255, 71, 103, .5), 0 0 26px rgba(255, 71, 103, .4); animation: targetPulse 1.4s ease-in-out infinite; }
.leader-card.targetable::before {
