/* ----------------------------- hand ----------------------------- */
.hand-panel {
  position: relative; z-index: 25;
  border-top: 1px solid rgba(255, 207, 92, .14);
  background: linear-gradient(180deg, rgba(9, 7, 19, .35), rgba(6, 5, 14, .92) 24%, #05040c);
  padding: 5px clamp(4px, 1vw, 14px) 2px;
  border-radius: 12px 12px 0 0;
}
.hand-toolbar {
  display: flex; align-items: center; gap: 10px; min-height: 42px;
  padding: 2px 2px 4px;
}
.toolbar-left { flex: 1; min-width: 0; display: flex; align-items: center; gap: 9px; }
.hand-title { font-family: var(--font-display); font-size: 15px; letter-spacing: 1.4px; color: #e9ddc6; white-space: nowrap; }
.hand-title span { color: var(--gold); }
.toolbar-hint { color: var(--muted); font-size: 10px; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.toolbar-hint b { color: var(--gold); }
.selected-actions { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }
.selected-info { min-width: 0; display: flex; align-items: baseline; gap: 7px; font-size: 10px; color: var(--muted); }
