  position: relative;
}
.hand-card {
  width: var(--hand-w); height: var(--hand-h);
  margin-left: calc(var(--hand-w) * -.22);
  transform-origin: 50% 100%;
  transform: translateY(var(--ty, 0)) rotate(var(--rot, 0deg));
  z-index: calc(10 + var(--i, 0));
  flex: 0 0 auto;
}
.hand-card:first-child { margin-left: 0; }
.hand-card:hover { transform: translateY(calc(var(--ty, 0px) - 18px)) rotate(0deg) scale(1.05); z-index: 60; }
.hand-card.selected { transform: translateY(calc(var(--ty, 0px) - 22px)) rotate(0deg) scale(1.06); border-color: var(--gold); box-shadow: 0 0 0 2px rgba(255, 207, 92, .5), 0 0 30px rgba(255, 138, 30, .38); z-index: 61; }
.hand-card.selected-combo { transform: translateY(calc(var(--ty, 0px) - 24px)) rotate(0deg) scale(1.04); border-color: var(--cyan); box-shadow: 0 0 0 2px rgba(111, 231, 255, .5), 0 0 30px rgba(111, 231, 255, .35); z-index: 61; }
