function drawCards(state, side, n) {
  const events = [];
  const s = getSide(state, side);
  for (let i = 0; i < n; i++) {
    if (state.over) break;
    if (!s.deck.length) {
      endGame(state, otherSide(side), 'deckout');
      events.push({ type: 'gameover', winner: state.winner, reason: state.reason });
      break;
