async (page) => {
  const log = [];
  for (let step = 0; step < 80; step++) {
    const info = await page.evaluate(() => {
      const state = window.DBFW_UI && DBFW_UI.state;
      const modal = document.querySelector('.modal');
      return {
        modal: modal ? (modal.getAttribute('aria-label') || modal.querySelector('.modal-title')?.textContent || '') : '',
        modalButtons: modal ? Array.from(modal.querySelectorAll('button')).map(b => b.textContent.trim()) : [],
        over: state ? !!state.over : null,
        active: state ? state.active : null,
        phase: state ? state.phase : null,
        aiBusy: DBFW_UI.view.aiBusy,
        round: state ? state.round : null,
        playerLife: state ? state.player.life.length : null,
        aiLife: state ? state.ai.life.length : null,
        playerField: state ? state.player.battle.length : null,
        aiField: state ? state.ai.battle.length : null
      };
    });
    log.push(info);

    if (info.over) break;

    if (info.modal) {
      const pick = info.modalButtons.find(t => /Take the Hit/i.test(t)) ||
                   info.modalButtons.find(t => /Strike/i.test(t)) ||
                   info.modalButtons.find(t => /^Close$/i.test(t));
      if (!pick) {
        log.push({ stuckModal: info.modal, buttons: info.modalButtons });
        break;
      }
      await page.evaluate((label) => {
        const btn = Array.from(document.querySelectorAll('.modal button')).find(b => b.textContent.trim() === label);
        if (btn) btn.click();
      }, pick);
      await page.waitForTimeout(500);
      continue;
    }

    if (info.active === 'player' && !info.aiBusy && (info.phase === 'main' || info.phase === 'charge')) {
      const clicked = await page.evaluate(() => {
        const btn = Array.from(document.querySelectorAll('.hand-toolbar button')).find(b => /End Turn/i.test(b.textContent));
        if (btn) { btn.click(); return true; }
        return false;
      });
      if (!clicked) { log.push({ noEndTurn: true }); break; }
    }
    await page.waitForTimeout(600);
  }
  return { last: log[log.length - 1], steps: log.length, log };
}

